#if UNITY_EDITOR
using Hadal.Gameplay.Art;
using UnityEditor;
using UnityEngine;

namespace Hadal.EditorTools
{
    /// <summary>
    /// Import rules for FBX files generated by art/blender/generate.py (Assets/_Hadal/Art/):
    /// HAD_* materials map to the palette, ANIM_* parts get an <see cref="ArtAnimator"/>.
    /// </summary>
    public sealed class HadalArtImporter : AssetPostprocessor
    {
        private const string ArtRoot = "Assets/_Hadal/Art/";

        private static bool IsHadalArt(string path) => path.StartsWith(ArtRoot) && path.EndsWith(".fbx", System.StringComparison.OrdinalIgnoreCase);

        private void OnPreprocessModel()
        {
            if (!IsHadalArt(assetPath))
                return;

            var importer = (ModelImporter)assetImporter;
            importer.globalScale = 1f;
            importer.useFileScale = true;
            importer.importCameras = false;
            importer.importLights = false;
            importer.importAnimation = false;
            importer.animationType = ModelImporterAnimationType.None;
            importer.isReadable = false;
            importer.meshCompression = ModelImporterMeshCompression.Medium;
            importer.importNormals = ModelImporterNormals.Import;
            importer.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
            importer.materialLocation = ModelImporterMaterialLocation.InPrefab;

            foreach (var name in HadalArtPalette.Names)
            {
                var material = HadalArtPalette.Load(name);
                if (material == null)
                    continue;

                importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), HadalArtPalette.Prefix + name), material);
            }
        }

        private void OnPostprocessModel(GameObject root)
        {
            if (!IsHadalArt(assetPath))
                return;

            foreach (var t in root.GetComponentsInChildren<Transform>(true))
            {
                if (!ArtAnimator.TryParse(t.name, out var mode, out var axis, out var speed))
                    continue;

                var animator = t.gameObject.AddComponent<ArtAnimator>();
                animator.Configure(mode, axis, speed);
            }
        }
    }
}
#endif
